void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // --- REGLAGE DU ZOOM ---
    float zoom = 3.0; // Grossissement x3 (Change cette valeur !)

    // Calcul des UVs centrés
    vec2 uv = fragCoord / iResolution.xy;

    // Formule de zoom centrée sur (0.5, 0.5)
    uv = (uv - 0.5) / zoom + 0.5;

    // Sécurité : si on zoome trop en arrière, on évite de répéter l'image
    if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
        fragColor = vec4(0.0);
        return;
    }



    vec2 psi = texture(iChannel0, uv).xy;
    float V = texture(iChannel1, uv).r * 50.0;

    float probability = dot(psi, psi);

    // === MODIFICATION ICI : BOOST DE LUMINOSITÉ ===
    // On multiplie par 20.0 ou 50.0 au lieu de 10.0
    // On peut aussi utiliser une racine carrée pour mieux voir les faibles densités
    float brightness = sqrt(probability) * 25.0; 

    float phase = atan(psi.y, psi.x);
    vec3 phaseColor = 0.5 + 0.5 * cos(phase + vec3(0, 2, 4));

    vec3 col = phaseColor * brightness;

    // On visualise le piège en fond (optionnel, pour voir le "bol")
    col += vec3(0.1) * (probability < 0.001 ? 1.0 : 0.0); 

    fragColor = vec4(col, 1.0);
}

// === PHYSIQUE ===
#define TAU 0.025
#define DT_BASE 0.09    // Vitesse de base du temps
#define SUNDMAN_K 0.9 // Force du ralentissement (Matrix effect)
#define HBAR 1.0
#define MASS 1.0

// === MATHS COMPLEXES ===
#define I vec2(0.0, 1.0)

vec2 cmul(vec2 a, vec2 b) { return vec2(a.x*b.x - a.y*b.y, a.x*b.y + a.y*b.x); }
vec2 cexp(float theta) { return vec2(cos(theta), sin(theta)); }
vec4 load(sampler2D channel, ivec2 p) { return texelFetch(channel, p, 0); }

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 p = ivec2(fragCoord);
    ivec2 res = ivec2(iResolution.xy);
    vec2 uv = fragCoord / iResolution.xy;

    // === INITIALISATION ===
    if (iFrame == 0) {
        vec2 center = iResolution.xy * 0.5;
        vec2 dist = fragCoord - center;
        float envelope = exp(-dot(dist, dist) * 0.001);
        vec2 phase = cexp(dist.x * 0.1);
        fragColor = vec4(envelope * phase, 0.0, 1.0);
        return;
    }

    // === CONDITIONS AUX BORDS (Dirichlet ψ=0) ===
    if (p.x <= 0 || p.x >= res.x-1 || p.y <= 0 || p.y >= res.y-1) {
        fragColor = vec4(0.0, 0.0, 0.0, 1.0);
        return;
    }

    // === LECTURE PSI ===
    vec2 psi = load(iChannel0, p).xy;

    // === LAPLACIEN (5-point stencil) ===
    vec2 psi_r = load(iChannel0, p + ivec2(1,0)).xy;
    vec2 psi_l = load(iChannel0, p - ivec2(1,0)).xy;
    vec2 psi_u = load(iChannel0, p + ivec2(0,1)).xy;
    vec2 psi_d = load(iChannel0, p - ivec2(0,1)).xy;

    vec2 laplacian = psi_r + psi_l + psi_u + psi_d - 4.0 * psi;
    vec2 kinetic = -0.5 * (HBAR*HBAR/MASS) * laplacian;

    // === POTENTIEL ===
    float V_poisson = texture(iChannel1, uv).r;
    vec2 center = iResolution.xy * 0.5;
    vec2 d = fragCoord - center;
    float V_trap = 0.0001 * dot(d, d);
    float V = V_poisson + V_trap;

    // === SUNDMAN ===
    float V_center = texture(iChannel1, vec2(0.5)).r;
    float dt = DT_BASE / (1.0 + SUNDMAN_K * abs(V_center));

    // === SCHRÖDINGER : i∂ψ/∂t = Hψ ===
    vec2 H_psi = kinetic + V * psi;
    vec2 d_psi = cmul(-I, H_psi);  // -i * H * psi

    vec2 psi_new = psi + d_psi * dt;

    // === NORMALISATION LOCALE (approximation) ===
    // Préserve la norme locale pour éviter l'explosion
    float norm_old = length(psi);
    float norm_new = length(psi_new);
    if (norm_new > 1e-10) {
        psi_new *= norm_old / norm_new;  // ✅ Conservation locale
    }

    fragColor = vec4(psi_new, 0.0, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 p = ivec2(fragCoord);
    ivec2 res = ivec2(iResolution.xy);

    // === BORDS : V = 0 (Dirichlet) ===
    if (p.x <= 0 || p.x >= res.x-1 || p.y <= 0 || p.y >= res.y-1) {
        fragColor = vec4(0.0);
        return;
    }

    // === SOURCE ===
    vec2 psi = load(iChannel0, p).xy;
    float density = dot(psi, psi);

    // === ÉTAT SOLVEUR ===
    vec4 state = load(iChannel1, p);
    float V = state.r;
    vec2 P = state.gb;

    // === PRIMAL : V update ===
    vec2 P_l = load(iChannel1, p - ivec2(1,0)).gb;
    vec2 P_d = load(iChannel1, p - ivec2(0,1)).gb;
    float div_P = (P.x - P_l.x) + (P.y - P_d.y);

    float V_new = V + TAU * (div_P + density);  // Source = +density (attractif)

    // === DUAL : P update avec PROJECTION ===
    float V_r = load(iChannel1, p + ivec2(1,0)).r;
    float V_u = load(iChannel1, p + ivec2(0,1)).r;
    vec2 grad_V = vec2(V_r - V_new, V_u - V_new);  // Semi-implicite

    vec2 P_new = P + TAU * grad_V;

    // Projection sur boule (régularisation TV-like, optionnel)
    float lambda = 1.0;  // Paramètre de régularisation
    P_new = P_new / max(1.0, length(P_new) / lambda);

    fragColor = vec4(V_new, P_new, 1.0);
}
